/**
 * Generated by scripts/generate-release-history-types.ts from the JSON Schemas in
 * release_history/schemas/. Do not edit: change a schema, then run
 * `bun run scripts/generate-release-history-types.ts` in frontend/.
 */

/**
 * A file's `<panel>/attempts/<digest>.json` (`release_history/cli.py`, `AttemptReport`): how the latest attempt at a file ended when it stored nothing. Replaced at each attempt, removed once the point or a stored gap is written; finalize reads it into the manifest's state for the file. Version 1: every key listed here is required and no other key is allowed. A key added later is declared here with the version that added it, and is not required, so the documents already written stay valid and no format version moves.
 */
export interface AttemptReport {
  format_version: 1;
  kind: "release_history.attempt";
  country: string;
  panel_id: string;
  /**
   * The file's sha256, as the series listed it.
   */
  digest: string;
  build_id: string;
  attempt: number;
  last_attempt: boolean;
  /**
   * `interrupted`: written before each stage and never replaced, so the run died there; `failed`: rewritten after a handled failure.
   */
  status: "interrupted" | "failed";
  stage: string;
  reason: string;
  error_class: string | null;
  at: string;
  producer: {
    version: string;
    commit: string | null;
  };
}

/**
 * A country's labels.json (`release_history/cli.py`, `labels_document`): what the page shows for each reform. Replaceable, so a corrected label needs no new panel; finalize copies it into every timeline. Version 1: every key listed here is required and no other key is allowed. A key added later is declared here with the version that added it, and is not required, so the documents already written stay valid and no format version moves.
 */
export interface LabelsDocument {
  format_version: 1;
  kind: "release_history.labels";
  country: string;
  /**
   * By reform id.
   */
  reforms: {
    [k: string]: {
      label: string | null;
      /**
       * Where the reform is defined, as the spec gives it.
       */
      source: {
        [k: string]: unknown;
      } | null;
    };
  };
}

/**
 * A panel's panel.json (`release_history/engine.py`): what its id hashes, and the engine it names. Written once. Version 1: every key listed here is required and no other key is allowed. A key added later is declared here with the version that added it, and is not required, so the points already stored stay valid and no format version moves.
 */
export interface PanelDocument {
  format_version: 1;
  kind: "release_history.panel";
  /**
   * sha256 of the canonical JSON of panel_key.
   */
  panel_id: string;
  panel_key: {
    country: string;
    policyengine: string;
    model: string;
    core: string;
    producer_version: string;
    point_format_version: number;
    spec_sha256: string;
  };
  digest_algorithm: string;
  country: string;
  engine: {
    policyengine: string;
    bundle_sha256: string;
    model: {
      name: string;
      version: string;
      wheel_sha256: null | string;
    };
    core: {
      name: string;
      version: string;
    };
  };
  producer_version: string;
  point_format_version: number;
  spec_sha256: string;
  /**
   * The spec as written, less what changes no number; parse_spec checks it.
   */
  definition: {
    [k: string]: unknown;
  };
}

/**
 * One file to measure, as the plan names it: written by `frontend/scripts/release-history.ts` (`plan`), read by `release_history/releases.py` (`Point.from_json`) in each measure job. A recorded build at one commit of the release repository. Version 1: every key listed here is required and no other key is allowed. A key added later is declared here with the version that added it, and is not required, so the documents already written stay valid and no format version moves.
 */
export interface PlannedPoint {
  build_id: string;
  release_directory: string;
  hf_repo: string;
  hf_commit: string;
  /**
   * The file the series listed; the producer refuses a different one.
   */
  digest: string;
  attempt: number;
  /**
   * A partial result (a reform failed) is stored only on the last attempt.
   */
  last_attempt: boolean;
}

/**
 * One data file measured on one panel (`release_history/document.py`): immutable once written. Version 1: every key listed here is required and no other key is allowed. A key added later is declared here with the version that added it, and is not required, so the points already stored stay valid and no format version moves.
 */
export interface MeasurementDocument {
  format_version: 1;
  kind: "release_history.measurement";
  country: string;
  panel_id: string;
  /**
   * sha256 of the canonical JSON of {h5_sha256, panel_id}.
   */
  measurement_id: string;
  status: "ok" | "partial" | "refused";
  /**
   * Why a refused point is a gap: a refusal the file itself causes.
   */
  reason: string | null;
  /**
   * Where the file was read from: an audit trail, never a listing fact.
   */
  fetched_from: {
    build_id: string;
    hf_repo: string;
    /**
     * Null for a build folder measured before it is published (measure --build-dir).
     */
    hf_commit: string | null;
    release_manifest: {
      path: string;
      sha256: string;
      json_sha256: string;
    };
    build_manifest: null | {
      path: string;
      sha256: string;
    };
    dataset: {
      key: string;
      path: string;
    };
    /**
     * What the build the point was fetched through declares about its file.
     */
    declared: {
      build: string | null;
      cut_tag: string | null;
      /**
       * Copied as the upstream document holds it; its shape is that document's.
       */
      migrated_from: unknown;
      built_at: string | null;
      /**
       * Copied as the upstream document holds it; its shape is that document's.
       */
      built_with_model: unknown;
      /**
       * Copied as the upstream document holds it; its shape is that document's.
       */
      built_with_core: unknown;
      /**
       * Copied as the upstream document holds it; its shape is that document's.
       */
      compatible_models: unknown;
      reference_model_compatibility: "inside" | "outside" | "undeclared" | "unreadable";
      description: string | null;
      build_provenance: null | {
        code_repository: string | null;
        code_commit: string | null;
        attempt_id: string | null;
        target_surface_sha256: string | null;
        n_targets: number | null;
        /**
         * Copied as the upstream document holds it; its shape is that document's.
         */
        target_registry_version: unknown;
        /**
         * Copied as the upstream document holds it; its shape is that document's.
         */
        household_weight_year: unknown;
        /**
         * Copied as the upstream document holds it; its shape is that document's.
         */
        runtime: unknown;
      };
    };
  };
  file: {
    sha256: string;
    bytes: number | null;
  };
  data: null | {
    columns_sha256: string;
    column_count: number;
    unknown_columns: string[];
    warnings: string[];
  };
  /**
   * @minItems 1
   */
  periods: {
    period: number;
    label: string;
  }[];
  baseline: null | {
    status: string;
  };
  reforms: null | {
    [k: string]: {
      status: "ok" | "error";
      definition_sha256: null | string;
      applied: null | {
        [k: string]: unknown;
      };
      error: null | {
        stage: string;
        class: string;
        name: string | null;
        where: string | null;
      };
    };
  };
  cells: {
    output: string;
    period: number;
    unit: "currency" | "count" | "rate" | "ratio";
    value: number | null;
    status: "ok" | "withheld";
    reason: string | null;
  }[];
  disclosure: {
    policy: "none" | "source_household_small_cells";
    min_source_households: number;
    withheld_cells: number | null;
  };
  engine_bundle: null | {
    bundle_id: string | null;
    /**
     * Copied as the upstream document holds it; its shape is that document's.
     */
    capital_gains_responses: unknown;
  };
  environment: {
    python: string;
    platform: string;
    packages: string[];
    packages_sha256: string;
    uv_lock_sha256: null | string;
  };
  producer: {
    version: string;
    commit: string | null;
  };
  runtime: {
    started_at: string | null;
    finished_at: string | null;
    seconds: number | null;
    runner: string | null;
    simulations: {
      label: string;
      seconds: number;
      peak_rss_bytes: number;
    }[];
    /**
     * The runner limits the point ran under (the spec's runner block); a point using warn_at of one is flagged.
     */
    limits: {
      seconds: number | null;
      memory_bytes: number | null;
      dataset_bytes: number | null;
      warn_at: number;
    };
    /**
     * The limits the run came within 20% of (a share of at least limits.warn_at), by limit name, with the share of the limit it used, rounded to 3 places. Computed once by the producer; the TypeScript finalize reads it for the manifest's nearLimits.
     */
    near_limits: {
      limit: "dataset" | "memory" | "seconds";
      share: number;
    }[];
  };
}

/**
 * A country's builds as its release repository's releases.json lists them, each with its file (`release_history/series.py`). Replaced each run. Version 1: every key listed here is required and no other key is allowed. A key added later is declared here with the version that added it, and is not required, so the points already stored stay valid and no format version moves.
 */
export interface SeriesRecord {
  format_version: 1;
  kind: "release_history.series";
  country: string;
  release_repo: string;
  rule: {
    /**
     * @minItems 1
     */
    releases: string[];
    since: null | string;
  };
  revision: string;
  commit: string;
  listed_at: string;
  record: {
    present: boolean;
    sha256: null | string;
    default: string | null;
  };
  lines: {
    release: string;
    present: boolean;
    role: string | null;
  }[];
  builds: {
    build_id: string;
    release: string;
    build: string;
    release_directory: string;
    published_at: string;
    withdrawn: boolean;
    current: boolean;
    in_default_release: boolean;
    role: string | null;
    digest: null | string;
    dataset_path: string | null;
    release_manifest_sha256: null | string;
    listing_status: "ok" | "refused";
    listing_reason: string | null;
  }[];
}

/**
 * A panel's numbers on its country's series axis, as `buildTimeline` in frontend/lib/microcosm/release-history-store.ts writes them (camelCase). Rebuilt by every finalize. Version 1: every key listed here is required and no other key is allowed. A key added later is declared here with the version that added it, and is not required, so the points already stored stay valid and no format version moves.
 */
export interface Timeline {
  formatVersion: 1;
  kind: "release_history.timeline";
  country: string;
  panelId: string;
  builtAt: string;
  listing: {
    commit: string;
    listedAt: string;
    rule: {
      releases: string[];
      since: string | null;
    };
  };
  /**
   * Keyed by the spec's reform ids.
   */
  labels: {
    [k: string]: {
      label: string | null;
      /**
       * Copied as the upstream document holds it; its shape is that document's.
       */
      source: unknown;
    };
  };
  builds: {
    buildId: string;
    release: string;
    build: string;
    publishedAt: string;
    current: boolean;
    withdrawn: boolean;
    digest: string;
    sameFileAs: null | string;
    state: "measured" | "gap" | "retrying" | "failed" | "missing";
    measurementId: null | string;
    status: null | "ok" | "partial" | "refused";
    reason: string | null;
    /**
     * Whether the reference model is inside the range the build declares; null where the panel holds no point.
     */
    referenceModelCompatibility: null | "inside" | "outside" | "undeclared" | "unreadable";
    /**
     * Columns of the file the reference model does not define; null where the panel holds no point or the point is a gap.
     */
    unknownColumns: null | string[];
  }[];
  outputs: {
    output: string;
    period: number;
    unit: "currency" | "count" | "rate" | "ratio";
    reference: null | {
      status: "resolved" | "citation" | "none";
      modelSignValue?: number;
      [k: string]: unknown;
    };
    /**
     * Items: One build's value. A withheld value carries its status and no reason.
     */
    values: {
      buildId: string;
      value: number | null;
      status: "ok" | "withheld" | "missing" | "unmeasured";
      comparedWith: null | string;
      change: number | null;
      relativeChange: number | null;
      changePoints: number | null;
      changeStatus: "ok" | "withheld" | "none";
    }[];
  }[];
  chronicle: null | {
    [k: string]: unknown;
  };
}
